/* cppi::1410fcfdc7910ac88e3528aea03d8188ede9f8f6d87cfd0aa84e1370031e4db4 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-05-26' and end_date = '2025-05-26')
and start_date = '2025-05-26' and end_date = '2025-05-26'

/* cppi::1410fcfdc7910ac88e3528aea03d8188ede9f8f6d87cfd0aa84e1370031e4db4 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-05-26' and end_date = '2025-05-26')
and start_date = '2025-05-26' and end_date = '2025-05-26'

